insert into public.shorts
  (id, title, director, year, runtime_sec, source, video_id, channels, pedigree, synopsis, thumb)
values
  ('fresh-guacamole', 'Fresh Guacamole', 'PES', 2012, 100, 'youtube', 'dNJdJIwCF_Y', ARRAY['funny']::text[], 'Academy Award nomination, Best Animated Short Film, 2013 — the shortest film ever Oscar-nominated', 'Dice, a baseball and a live grenade stand in for the ingredients as PES stop-motion animates a bowl of guacamole into existence, one substitution at a time.', 'https://i.ytimg.com/vi/dNJdJIwCF_Y/hqdefault.jpg'),
  ('curmudgeons', 'Curmudgeons', 'Danny DeVito', 2016, 1010, 'vimeo', '159449591', ARRAY['funny']::text[], 'Tribeca Film Festival 2016 — Best Narrative Short nomination · Vimeo''s first official Staff Pick Premiere', 'Two elderly men at an assisted-living home rekindle a decades-old, foul-mouthed friendship neither of their families quite know what to do with.', 'https://i.vimeocdn.com/video/595328997-f40302e304f9c6c8fc4004a7fc9d125664c92a6415131f109169cd9895adc637-d_295x166?region=us'),
  ('noah', 'Noah', 'Patrick Cederberg & Walter Woodman', 2013, 1072, 'vimeo', '65935223', ARRAY['grown']::text[], 'Won Best Canadian Short Film, Toronto International Film Festival 2013', 'A teenager''s breakup unfolds entirely inside his laptop screen — Skype, Chatroulette, Facebook — as the relationship comes apart in real time.', 'https://i.vimeocdn.com/video/437141128-a4e28582cb683f64197d8c22d692be727804ac4d54b1a847033d5a8391baae99-d_640?region=us'),
  ('fauve', 'Fauve', 'Jeremy Comte', 2018, 984, 'vimeo', '293033666', ARRAY['grown']::text[], 'Sundance 2018 — Special Jury Prize, Short Film (won) · Academy Award nomination, Best Live Action Short Film, 2019', 'Two boys roaming an abandoned surface mine escalate a game of dares until the landscape itself turns on them.', 'https://i.vimeocdn.com/video/765177751-42646a9dc74fe21a9938054ef56050cfb251ba93917a78d3c0008a273bd8defb-d_295x166?region=us'),
  ('will-you-look-at-me', 'Will You Look at Me', 'Shuli Huang', 2022, 1209, 'vimeo', '1006042481', ARRAY['loud']::text[], 'Cannes Critics'' Week 2022 — Queer Palm (won) · Sundance 2023 — Short Film Jury Award, Nonfiction (won)', 'A young gay filmmaker returns to his rural Chinese hometown and finally has the conversation with his mother that both of them have been avoiding for years.', 'https://i.vimeocdn.com/video/1922734229-6ac0d62ca45fedcc955eb77eca94a3bd774c96e65119b82fc6c6963783a60df8-d_295x166?region=us'),
  ('the-confession', 'The Confession', 'Tanel Toom', 2010, 1523, 'vimeo', '76111983', ARRAY['wrong']::text[], 'Academy Award nomination, Best Live Action Short Film, 2011', 'Two nine-year-old boys stage a fake sin to confess, and the prank spirals into an accidental death they then have to cover up.', 'https://i.vimeocdn.com/video/450890267-a595bd1fdde6486ff98d9acfd52908033938df35989bf57e82fa141e1334f887-d_640?region=us'),
  ('brotherhood', 'Brotherhood', 'Meryam Joobeur', 2018, 1507, 'vimeo', '363649438', ARRAY['wrong']::text[], 'Won Best Canadian Short Film, TIFF 2018 · Academy Award nomination, Best Live Action Short Film, 2020', 'A Tunisian shepherd grows suspicious of his son, freshly returned from fighting in Syria with a veiled wife nobody in the family has met.', 'https://i.vimeocdn.com/video/846297217-b2b88e972a0513a9dfc79f866452955bf0417b9ee0895eae4c7d9d962cfe2ca5-d_295x166?region=us'),
  ('uncanny-valley', 'Uncanny Valley', 'Federico Heller', 2015, 533, 'vimeo', '147365861', ARRAY['future']::text[], 'Annecy International Animated Film Festival — Official Selection · Animago Award 2016, Best Short (won)', 'In a near-future slum, a virtual-reality gaming addict starts to suspect the ultra-violent game he''s jacked into is feeding on something real.', 'https://i.vimeocdn.com/video/546078021-649439381b8fd58528221a11e387b3fff5ac46fa008567072a49a2dc3399a424-d_295x166?region=us'),
  ('colette', 'Colette', 'Anthony Giacchino', 2020, 1440, 'youtube', 'J7uBf1gD6JY', ARRAY['front']::text[], 'Academy Award, Best Documentary Short Subject (won), 2021', 'A 90-year-old former French Resistance fighter travels to Germany for the first time since the war, to visit the camp where her brother died as a slave laborer.', 'https://i.ytimg.com/vi/J7uBf1gD6JY/hqdefault.jpg'),
  ('the-last-repair-shop', 'The Last Repair Shop', 'Ben Proudfoot & Kris Bowers', 2023, 2340, 'youtube', 'xttrkgKXtZ4', ARRAY['sound']::text[], 'Academy Award, Best Documentary Short Film (won), 2024', 'Four Los Angeles school-district technicians keep 80,000 free instruments playable for public-school kids, and the work quietly remakes each of their own lives.', 'https://i.ytimg.com/vi/xttrkgKXtZ4/hqdefault.jpg'),
  ('instruments-of-a-beating-heart', 'Instruments of a Beating Heart', 'Ema Ryan Yamazaki', 2024, 1380, 'youtube', 'DRW0auOiqm4', ARRAY['sound']::text[], 'IDA Documentary Awards 2024 — Best Short (won) · Academy Award nomination, Best Documentary Short Film, 2025', 'Tokyo first-graders are pushed to master Beethoven''s "Ode to Joy" on real instruments in time for a school ceremony.', 'https://i.ytimg.com/vi/DRW0auOiqm4/hqdefault.jpg'),
  ('the-last-ice-merchant', 'The Last Ice Merchant', 'Sandy Patch', 2012, 851, 'vimeo', '66507747', ARRAY['wild']::text[], 'Wild & Scenic Film Festival 2013 — Official Selection', 'One of the last traditional ice harvesters descends an Ecuadorian volcano alone, keeping up a mountain trade his own brothers already gave up.', 'https://i.vimeocdn.com/video/438211679-ba974322aa9824521c9b7f98b24fac93b8a5b217d4a7b1a3a1c0814eb819368e-d_295x166?region=us'),
  ('crying-glacier', 'Crying Glacier', 'Lutz Stautner', 2024, 840, 'youtube', '1AewKFS8uXg', ARRAY['wild']::text[], 'News & Documentary Emmy Award nomination, Outstanding Climate, Environment or Weather Coverage, 2025', 'A sound artist records the pops and groans of a rapidly melting Swiss glacier with hydrophones and contact mics, before there''s nothing left to record.', 'https://i.ytimg.com/vi/1AewKFS8uXg/hqdefault.jpg'),
  ('a-swim-lesson', 'A Swim Lesson', 'Rashida Jones & Will McCormack', 2024, 1260, 'youtube', 'k6ooMTKXAVk', ARRAY['over']::text[], 'Telluride Film Festival 2024 — Official Selection · Academy Award shortlist, Best Documentary Short Film, 2025', 'A veteran Los Angeles swim instructor teaches children to master their fear of the water, one small act of courage at a time.', 'https://i.ytimg.com/vi/k6ooMTKXAVk/hqdefault.jpg'),
  ('slomo', 'Slomo', 'Josh Izenberg', 2013, 974, 'vimeo', '59749737', ARRAY['over']::text[], 'Won Best Documentary Short, SXSW 2013 · Won Best Short, IDA Documentary Awards 2013', 'A former neurologist walks away from medicine entirely to spend his days rollerblading at high speed along a San Diego boardwalk.', 'https://i.vimeocdn.com/video/473524013-11ff1872da8f0340da18d66ca2df88c8ad49be70954ce22395f958a1727b38fc-d_295x166?region=us'),
  ('kung-fury', 'Kung Fury', 'David Sandberg', 2015, 1860, 'youtube', 'bS5P_LAqiVg', ARRAY['rails']::text[], 'Cannes Film Festival 2015 — Directors'' Fortnight, Official Selection', 'A kung-fu cop travels back in time to fight Nazis, Viking gods and a T-Rex, in a movie that never once takes its own premise seriously.', 'https://i.ytimg.com/vi/bS5P_LAqiVg/hqdefault.jpg'),
  ('the-cat-piano', 'The Cat Piano', 'Eddie White & Ari Gibson', 2009, 513, 'vimeo', '3985019', ARRAY['rails']::text[], 'AFI Award, Best Short Animation (won), 2009 · Academy Award shortlist, Best Animated Short Film, 2010', 'In a noir-toned city of singing cats, narrated by Nick Cave, a chain-smoking poet investigates who''s been abducting the town''s musical felines one by one.', 'https://i.vimeocdn.com/video/7305619-55f82613b5e2160a2ce3c6a11aae7966f7a3f83bf177872045109a5c9adb66b3-d_640?region=us')
